```javascript
const axios = require("axios");

async function getData(inputUrl) {
  try {
    const response = await axios.post(
      "https://fsave.net/proxy.php",
      `url=${encodeURIComponent(inputUrl)}&dt=${Date.now().toString().replace('.', '')}`,
      {
        headers: {
          "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
          "Accept": "*/*",
          "X-Requested-With": "XMLHttpRequest",
          "User-Agent": "Mozilla/5.0 (Linux; Android 12; Infinix X665E Build/SP1A.210812.016; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/150.0.7871.181 Mobile Safari/537.36",
          "Referer": "https://fsave.net/en"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

const facebookUrl = "https://www.facebook.com/share/r/18wcg5u7M7/";
getData(facebookUrl)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
